package app.maximus.lab.domain

/**
 * Concept questions ("Verständnisfragen"): no numbers to compute, no formula to remember by heart —
 * they test whether the physics is understood. The first option is correct; [why] explains the right
 * answer and, where useful, why the tempting wrong options fail.
 */
internal object QuizConcepts {
    private var n = 0
    private fun c(topic: Topic, diff: Int, chapter: String, prompt: String, correct: String, vararg wrong: String, why: String) =
        Question("cq-${topic.short}-${++n}", topic, diff, prompt, why, listOf(correct) + wrong, 0, chapterKey = chapter)

    private val T = Topic.THERMO
    private val E = Topic.ELECTRO
    private val Q = Topic.QUANTUM
    private val S = Topic.SEMICONDUCTOR
    private val C = Topic.CALORIC
    private val F = Topic.QFT
    private val K = Topic.MECHANICS
    private val M = Topic.MATH

