            "Im Gleichgewicht ist das Produkt der Ladungsträgerdichten unabhängig von der Dotierung.", "Elektronen und Löcher sind immer gleich viele.",
            "Die Dotierung erhöht beide Dichten.", "Es gilt nur in undotierten Halbleitern.",
            why = "Mehr Elektronen bedeuten mehr Rekombination, die Löcherdichte sinkt entsprechend. n_i hängt nur von Material und Temperatur ab (∝ e^{−E_g/2k_BT})."),
        c(S, 2, "sc_transport", "Was ist der Unterschied zwischen Drift- und Diffusionsstrom?",
            "Drift wird von einem elektrischen Feld getrieben, Diffusion von einem Konzentrationsgefälle.", "Drift gibt es nur für Löcher.",
            "Diffusion ist schneller als Drift.", "Es gibt keinen Unterschied.",
            why = "Im pn-Übergang im Gleichgewicht heben sich beide genau auf. Verknüpft sind sie über die Einstein-Relation D = μk_BT/e."),
        c(S, 2, "sc_pn", "Wie entsteht die Raumladungszone im pn-Übergang?",
            "Majoritätsträger diffundieren über die Grenze und rekombinieren; zurück bleiben ortsfeste ionisierte Dotieratome.",
            "Durch eine äußere Spannung beim Herstellen.", "Durch Verunreinigungen an der Grenzfläche.", "Weil sich Elektronen an der Grenze stauen.",
            why = "Die ionisierten Donatoren (+) und Akzeptoren (−) erzeugen ein Feld, das die weitere Diffusion stoppt: Gleichgewicht bei der Diffusionsspannung."),
        c(S, 2, "sc_pn", "Warum leitet eine Diode in Durchlassrichtung exponentiell besser?",
            "Die Spannung senkt die Potentialbarriere, und die Zahl der Träger, die sie überwinden, wächst wie e^{eU/k_BT}.",
            "Weil der Widerstand mit der Spannung linear sinkt.", "Weil die Diode warm wird.", "Weil die Raumladungszone breiter wird.",
            why = "Boltzmann-Faktor: Shockley-Gleichung I = I_s(e^{eU/k_BT} − 1). In Sperrrichtung bleibt nur der kleine Sättigungsstrom."),
        c(S, 2, "sc_opto", "Warum liefert eine Solarzelle maximal eine Leerlaufspannung unterhalb von E_g/e?",
            "Rekombination und die thermische Besetzung begrenzen die Aufspaltung der Quasi-Fermi-Niveaus.", "Weil Licht keine Energie über E_g hat.",
            "Weil die Elektronen zu langsam sind.", "Wegen des Widerstands der Kontakte allein.",
            why = "U_oc = (k_BT/e) ln(I_ph/I_s + 1) < E_g/e. Photonen über E_g geben den Überschuss als Wärme ab (Thermalisierung) — Teil der Shockley-Queisser-Grenze."),
        c(S, 3, "sc_transistor", "Wie schaltet ein MOSFET?",
            "Die Gate-Spannung erzeugt über das Oxid eine Inversionsschicht, die Source und Drain leitend verbindet.",
            "Durch einen Steuerstrom in die Basis.", "Durch Erwärmung des Kanals.", "Durch ein Magnetfeld am Gate.",
            why = "Feldeffekt: Ab der Schwellspannung sammeln sich Minoritätsträger unter dem Gate. Fast kein Gate-Strom — deshalb so sparsam in CMOS-Logik."),

        // ---------------- Kalorik ----------------
        c(C, 1, "ca_thermo", "Was ist der gemeinsame Kern aller kalorischen Effekte?",
            "Ein äußeres Feld ändert die Ordnung (Entropie) eines Freiheitsgrads; adiabatisch geht das als Temperaturänderung ins Gitter.",
            "Ein Feld erzeugt direkt Wärme durch Joulesche Verluste.", "Ein Feld ändert die Masse des Materials.", "Es sind chemische Reaktionen.",
            why = "Bei konstanter Gesamtentropie muss eine feldinduzierte Entropieänderung ΔS_Feld durch die Gitterentropie ausgeglichen werden: ΔT_ad ≈ −T ΔS_Feld/c."),
        c(C, 2, "ca_thermo", "Warum sind kalorische Effekte nahe einem Phasenübergang am größten?",
            "Dort ändert sich die Ordnung schon bei kleinen Feldern stark, die Entropieänderung pro Feld ist maximal.", "Weil das Material dort am kältesten ist.",
            "Weil die Wärmekapazität dort null ist.", "Weil dort keine Hysterese auftritt.",
            why = "Maxwell-Relationen wie (∂S/∂E)_T = (∂P/∂T)_E sind groß, wenn der Ordnungsparameter steil von T abhängt. Nachteil: Hysterese bei Übergängen 1. Ordnung."),
        c(C, 2, "ca_electro", "Was passiert beim elektrokalorischen Effekt, wenn man ein Feld adiabatisch anlegt?",
            "Die Dipole richten sich aus, ihre Entropie sinkt, das Material erwärmt sich.", "Das Material kühlt sich ab.",
            "Nichts, bis man das Feld wieder abschaltet.", "Es fließt ein Strom, der Wärme erzeugt.",
            why = "Abkühlung kommt beim Abschalten: Die Dipole verlieren ihre Ordnung und nehmen Entropie aus dem Gitter. Ein Kühlzyklus koppelt beides mit Wärmeübertragung."),
        c(C, 2, "ca_elasto", "Warum erwärmt sich ein Gummiband beim schnellen Dehnen?",
            "Die Polymerketten werden geordnet, ihre Konfigurationsentropie sinkt, die Energie geht in Gitterschwingungen.",
            "Durch Reibung zwischen den Molekülen.", "Weil die Bindungen gespannt werden und Energie speichern.", "Weil es Feuchtigkeit verliert.",
            why = "Entropieelastizität: Die Rückstellkraft ist überwiegend entropisch. Auch Formgedächtnislegierungen (NiTi) zeigen über die martensitische Umwandlung große elastokalorische Effekte."),
        c(C, 2, "ca_magneto_baro", "Wie funktioniert die adiabatische Entmagnetisierung zum Erreichen tiefer Temperaturen?",
            "Spins werden isotherm im Feld ausgerichtet, dann wird das Feld adiabatisch abgeschaltet; die Spins nehmen Entropie aus dem Gitter.",
            "Man erwärmt einen Magneten und kühlt ihn schnell.", "Ein starkes Feld bremst die Atome direkt ab.", "Durch Verdampfen von Helium im Magnetfeld.",
            why = "Mit paramagnetischen Salzen erreicht man Millikelvin, mit Kernspins Mikrokelvin. Der Kreisprozess ist das magnetische Gegenstück zur Gasexpansion."),
        c(C, 3, "ca_multi", "Was ist der Vorteil multikalorischer Materialien?",
            "Mehrere Felder (z. B. Magnetfeld und Druck) koppeln an dieselbe Umwandlung; man kann Hysterese umgehen und den Effekt vergrößern.",
            "Sie brauchen gar kein äußeres Feld.", "Sie sind billiger als Gase.", "Sie arbeiten ohne Wärmeübertragung.",
            why = "Mit zwei Feldern lässt sich der Zyklus so führen, dass die Umwandlung jeweils mit dem günstigeren Feld getrieben wird (Kreuzkopplung) — weniger Energieverlust pro Zyklus."),
        c(C, 2, "ca_calorimetry", "Warum unterscheiden sich direkt gemessene und über Maxwell-Relationen indirekt bestimmte ΔT oft?",
            "Die indirekte Methode setzt Gleichgewicht voraus und versagt bei Hysterese und Übergängen 1. Ordnung.", "Weil Thermometer ungenau sind.",
            "Weil Maxwell-Relationen nur für Gase gelten.", "Weil direkte Messungen immer zu groß sind.",
            why = "Maxwell-Relationen folgen aus der Existenz eines Gleichgewichtspotentials. Bei Hysterese hängt der Zustand von der Vorgeschichte ab; dann braucht man direkte oder quasi-direkte Messungen."),

        // ---------------- Quantenfeldtheorie ----------------
        c(F, 2, "qft_relativity", "Warum braucht man für relativistische Quantenmechanik Felder statt einer Ein-Teilchen-Wellenfunktion?",
            "Bei Energien ≳ mc² entstehen und vernichten sich Teilchen; die Teilchenzahl ist nicht erhalten.", "Weil die Schrödinger-Gleichung zu kompliziert ist.",
            "Weil Teilchen relativistisch keine Masse haben.", "Weil die Unschärferelation dort nicht gilt.",
            why = "Lokalisierung unter die Compton-Wellenlänge ħ/mc kostet genug Energie für Paarerzeugung. Felder mit Erzeugern und Vernichtern beschreiben variable Teilchenzahlen natürlich."),
        c(F, 2, "qft_classical", "Was liefert das Noether-Theorem für eine Feldtheorie mit globaler U(1)-Symmetrie?",
            "Einen erhaltenen Strom ∂_μ j^μ = 0 und damit eine erhaltene Ladung.", "Die Masse des Feldes.", "Die Kopplungskonstante.", "Eine Eichboson-Masse.",
            why = "Phasensymmetrie φ → e^{iα}φ ↔ Ladungserhaltung. Macht man die Symmetrie lokal, braucht man ein Eichfeld — so entsteht die QED."),
        c(F, 3, "qft_scalar", "Was ist der physikalische Inhalt der kanonischen Quantisierung eines freien Feldes?",
            "Jede Fourier-Mode ist ein harmonischer Oszillator; seine Anregungsquanten sind die Teilchen.", "Das Feld wird an jedem Punkt gemessen.",
            "Die Lichtgeschwindigkeit wird quantisiert.", "Teilchen sind kleine Kugeln im Feld.",
            why = "Erzeuger a†_p fügen ein Teilchen mit Impuls p hinzu. Die Nullpunktsenergien aller Moden sind die Vakuumenergie (in der Regel per Normalordnung abgezogen)."),
        c(F, 3, "qft_dirac", "Was sagte die Dirac-Gleichung vorher, das damals unbekannt war?",
            "Antiteilchen (das Positron).", "Das Neutrino.", "Die Masse des Protons.", "Die Feinstruktur ohne Spin.",
            why = "Die Lösungen negativer Energie werden als Antiteilchen interpretiert; 1932 fand Anderson das Positron. Außerdem folgen Spin ½ und g = 2 automatisch."),
        c(F, 2, "qft_feynman", "Was stellt eine innere Linie in einem Feynman-Diagramm dar?",
            "Einen Propagator — ein virtuelles Teilchen, das nicht auf der Massenschale liegen muss.", "Ein reales, messbares Teilchen.",
            "Die Bahn eines Teilchens im Raum.", "Eine Erhaltungsgröße.",
            why = "Diagramme sind Terme der Störungsreihe, keine Bahnen. Innere Linien tragen beliebige Viererimpulse (p² ≠ m²); an Vertizes gilt Impulserhaltung."),
        c(F, 3, "qft_renorm", "Was bedeutet es, dass die Kopplungskonstante „läuft“?",
            "Die effektive Stärke der Wechselwirkung hängt von der Energieskala ab, bei der man misst.", "Die Kopplung ändert sich mit der Zeit.",
            "Die Kopplung ist im Experiment nicht messbar.", "Die Theorie ist inkonsistent.",
            why = "Vakuumpolarisation: In der QED schirmt sie die Ladung ab (α wächst mit der Energie, 1/137 → 1/128 bei M_Z), in der QCD dominiert Anti-Abschirmung (asymptotische Freiheit)."),
        c(F, 3, "qft_sm", "Wie erhalten die W- und Z-Bosonen ihre Masse?",
            "Durch spontane Symmetriebrechung mit dem Higgs-Feld, dessen Vakuumerwartungswert nicht null ist.", "Sie sind von Natur aus schwer.",
            "Durch die starke Wechselwirkung.", "Durch Kopplung an das Photon.",
            why = "Ein expliziter Massenterm würde die Eichsymmetrie zerstören. Drei Goldstone-Moden werden zu den longitudinalen Freiheitsgraden von W± und Z; das Photon bleibt masselos."),

        // ---------------- Mechanik und Relativität ----------------
        c(K, 1, "me_newton", "Ein Astronaut auf der ISS schwebt. Warum?",
            "Er fällt zusammen mit der Station frei um die Erde; die Schwerkraft wirkt fast unvermindert.", "Im Orbit gibt es keine Schwerkraft.",
            "Die Zentrifugalkraft ist größer als die Schwerkraft.", "Der Luftdruck hebt ihn an.",
            why = "In 400 km Höhe ist g noch ≈ 90 % des Bodenwerts. Schwerelosigkeit bedeutet freien Fall: Station und Astronaut erfahren dieselbe Beschleunigung."),
        c(K, 2, "me_lagrange", "Was ist der praktische Vorteil des Lagrange-Formalismus gegenüber Newton?",
            "Zwangskräfte fallen heraus; man arbeitet direkt mit generalisierten Koordinaten und skalaren Energien.", "Er ist genauer als die Newtonschen Gesetze.",
            "Er gilt auch ohne Energieerhaltung nicht.", "Er braucht keine Anfangsbedingungen.",
            why = "Physikalisch gleichwertig, aber Zwangsbedingungen werden durch die Koordinatenwahl automatisch erfüllt; Symmetrien zeigen sich als zyklische Koordinaten."),
        c(K, 2, "me_hamilton", "Was beschreibt eine Bahn im Phasenraum?",
            "Den vollständigen Zustand (alle q und p) und seine Entwicklung; Bahnen kreuzen sich nie.", "Die räumliche Bahn eines Teilchens.",
            "Nur die Energie.", "Die Geschwindigkeit als Funktion der Zeit.",
            why = "Die Hamilton-Gleichungen sind erster Ordnung; durch jeden Phasenraumpunkt geht genau eine Lösung (Eindeutigkeit)."),
        c(K, 2, "me_rigid", "Warum kann eine Eiskunstläuferin ihre Pirouette beschleunigen, indem sie die Arme anzieht?",
            "Der Drehimpuls bleibt erhalten, das Trägheitsmoment sinkt, also steigt die Winkelgeschwindigkeit.", "Sie stößt sich vom Eis ab.",
            "Die Energie bleibt erhalten, also bleibt ω gleich.", "Weil die Luftreibung abnimmt.",
            why = "L = Iω konstant. Die Rotationsenergie L²/2I steigt dabei — die Arbeit leisten ihre Muskeln gegen die Zentrifugalkraft."),
        c(K, 2, "me_oscillation", "Warum ist Resonanz bei einer schwach gedämpften Schwingung gefährlich?",
            "Bei Anregung nahe der Eigenfrequenz wird die Amplitude etwa Q-mal größer als bei statischer Last.", "Weil sich dann die Eigenfrequenz ändert.",
            "Weil die Dämpfung bei Resonanz verschwindet.", "Weil die Schwingung dann chaotisch wird.",
            why = "A(ω₀) ≈ Q · f₀/ω₀². Brücken und Maschinen werden deshalb gedämpft oder ihre Eigenfrequenzen von Anregungsfrequenzen weggelegt."),
        c(K, 2, "me_sr", "Warum gibt es beim Zwillingsparadoxon keinen Widerspruch?",
            "Die Situation ist nicht symmetrisch: Nur der Reisende wechselt das Inertialsystem (Beschleunigung, Umkehr).",
            "Beide altern gleich schnell.", "Die Zeitdilatation ist nur scheinbar.", "Weil Licht beide Uhren gleich beeinflusst.",
            why = "Die Eigenzeit ist entlang der geraden (unbeschleunigten) Weltlinie maximal. Der Reisende hat zwischen denselben Ereignissen eine kürzere Weltlinie in der Minkowski-Metrik."),
        c(K, 2, "me_sr", "Warum kann ein Körper mit Masse die Lichtgeschwindigkeit nicht erreichen?",
            "Seine Energie γmc² würde unendlich; endliche Arbeit erhöht v nur asymptotisch gegen c.", "Weil der Luftwiderstand zu groß wird.",
            "Weil seine Masse dabei verschwindet.", "Weil es kein Bezugssystem mit v = c gibt, in dem Kraft wirkt.",
            why = "Für v → c divergiert γ = 1/√(1 − v²/c²). Teilchenbeschleuniger erhöhen die Energie, die Geschwindigkeit nähert sich c nur noch in den Nachkommastellen."),
        c(K, 3, "me_gr", "Warum gehen Uhren in einem stärkeren Gravitationsfeld langsamer?",
            "Die Metrik hängt vom Potential ab; die Eigenzeit dτ = √(1 + 2Φ/c²) dt ist bei tieferem Potential kleiner.",
            "Weil die Schwerkraft das Uhrwerk bremst.", "Weil Licht im Feld langsamer wird und die Uhr später abgelesen wird.", "Weil die Masse der Uhr zunimmt.",
            why = "Das gilt für jede Uhr, auch Atomuhren (Pound-Rebka, GPS). Es folgt schon aus dem Äquivalenzprinzip mit einem beschleunigten Fahrstuhl und dem Doppler-Effekt."),
        c(K, 2, "me_continuum", "Warum fliegt ein Flugzeug? Welche Aussage ist physikalisch korrekt?",
            "Die Tragfläche lenkt Luft nach unten; die Impulsänderung und der Druckunterschied (Bernoulli) sind zwei Beschreibungen desselben Auftriebs.",
            "Die Luft oben muss in derselben Zeit wie unten ankommen und ist deshalb schneller.", "Der Motor drückt das Flugzeug nach oben.",
            "Die Luft unter der Tragfläche ist dichter und trägt wie Wasser.",
            why = "Die „gleiche Laufzeit“-Erklärung ist falsch (oben ist die Luft sogar schneller). Auftrieb entsteht durch die Zirkulation um das Profil (Kutta-Joukowski)."),

        // ---------------- Mathematik ----------------
        c(M, 1, "ma_analysis", "Was bedeutet die Ableitung f'(x₀) geometrisch?",
            "Die Steigung der Tangente an den Graphen in x₀, also die lineare Näherung von f nahe x₀.", "Die Fläche unter dem Graphen bis x₀.",
            "Den Funktionswert in x₀.", "Die Krümmung des Graphen.",
            why = "f(x₀ + h) = f(x₀) + f'(x₀)h + o(h). Die Krümmung hängt mit der zweiten Ableitung zusammen."),
        c(M, 1, "ma_integral", "Was besagt der Hauptsatz der Differential- und Integralrechnung?",
            "Integrieren und Differenzieren sind zueinander inverse Operationen.", "Jede Funktion ist integrierbar.",
            "Das Integral ist immer positiv.", "Die Ableitung einer Konstanten ist eins.",
            why = "d/dx ∫ₐˣ f(t) dt = f(x) für stetiges f, und ∫ₐᵇ F'(x) dx = F(b) − F(a). Deshalb lassen sich Integrale über Stammfunktionen berechnen."),
        c(M, 2, "ma_series", "Warum konvergiert eine Potenzreihe innerhalb ihres Konvergenzradius und divergiert außerhalb?",
            "Sie verhält sich wie eine geometrische Reihe: Die Glieder fallen innen geometrisch ab und wachsen außen unbeschränkt.",
            "Weil Polynome immer konvergieren.", "Weil der Radius willkürlich festgelegt wird.", "Das gilt nur für reelle Zahlen.",
            why = "Wurzelkriterium mit limsup |aₙ|^{1/n} = 1/R. Auf dem Rand selbst ist alles möglich (Beispiel: Σxⁿ/n bei x = 1 und −1)."),
        c(M, 2, "ma_taylor", "Warum hat die Taylor-Reihe von 1/(1 + x²) um 0 nur den Konvergenzradius 1, obwohl die Funktion auf ganz ℝ glatt ist?",
            "Im Komplexen hat sie Pole bei ±i, also im Abstand 1 vom Entwicklungspunkt.", "Weil sie bei x = 1 nicht definiert ist.",
            "Weil Taylor-Reihen immer Radius 1 haben.", "Weil die Ableitungen bei 0 verschwinden.",
            why = "Der Konvergenzradius ist der Abstand zur nächsten Singularität in ℂ — ein schönes Beispiel, warum Funktionentheorie reelle Analysis erklärt."),
        c(M, 2, "ma_multidiff", "Was zeigt der Gradient einer Funktion f(x, y) an?",
            "Die Richtung des steilsten Anstiegs; er steht senkrecht auf den Höhenlinien.", "Die Richtung, in der f konstant bleibt.",
            "Den Funktionswert.", "Die zweite Ableitung.",
            why = "Richtungsableitung ∂_v f = ∇f · v ist für v ∥ ∇f maximal und für v ⊥ ∇f null (entlang der Höhenlinie)."),
        c(M, 2, "ma_implicit", "Was ist die geometrische Idee hinter Lagrange-Multiplikatoren?",
            "Im Extremum unter einer Nebenbedingung sind die Gradienten von Zielfunktion und Nebenbedingung parallel.",
            "Die Nebenbedingung wird einfach ignoriert.", "Die Zielfunktion muss linear sein.", "Der Gradient der Zielfunktion verschwindet immer.",
            why = "Längs der Nebenbedingungsfläche darf sich f in erster Ordnung nicht ändern: ∇f hat keine Komponente tangential zur Fläche, also ∇f = λ∇g."),
        c(M, 2, "ma_vector", "Was bedeutet div F > 0 in einem Punkt anschaulich?",
            "Der Punkt ist eine Quelle: Aus einem kleinen Volumen fließt netto mehr heraus als hinein.", "Das Feld wirbelt um den Punkt.",
            "Das Feld ist dort null.", "Das Feld ist konservativ.",
            why = "div F = lim (Fluss durch Oberfläche)/Volumen. Wirbel misst die Rotation; Gauß macht aus lokalen Quellen den Fluss durch beliebige Flächen."),
        c(M, 3, "ma_lebesgue", "Warum ist das Lebesgue-Integral für die Physik (z. B. L²-Räume der Quantenmechanik) wichtiger als das Riemann-Integral?",
            "Grenzwerte und Integrale lassen sich unter milden Bedingungen vertauschen, und L² wird vollständig (ein Hilbertraum).",
            "Es liefert für stetige Funktionen andere Werte.", "Es ist leichter auszurechnen.", "Weil Riemann-Integrale nur für Polynome existieren.",
            why = "Mit Riemann ist der Raum quadratintegrabler Funktionen nicht vollständig; Cauchy-Folgen von Wellenfunktionen hätten keinen Grenzwert. Für stetige Funktionen stimmen beide Integrale überein."),
        c(M, 2, "ma_linalg", "Was bedeutet det A = 0 für ein lineares Gleichungssystem Ax = b?",
            "A ist nicht invertierbar: Es gibt entweder keine oder unendlich viele Lösungen.", "Es gibt genau eine Lösung x = 0.",
            "Die Lösung ist x = b.", "A ist die Einheitsmatrix.",
            why = "det A = 0 ⇔ Kern nicht trivial ⇔ Spalten linear abhängig. Geometrisch drückt A Volumen auf null zusammen."),
        c(M, 2, "ma_linalg2", "Warum diagonalisiert man Matrizen in der Physik so gern?",
            "In der Eigenbasis entkoppeln die Gleichungen; jede Komponente entwickelt sich unabhängig (Normalmoden, stationäre Zustände).",
            "Damit die Determinante null wird.", "Weil Diagonalmatrizen immer symmetrisch sind.", "Weil sich dann die Eigenwerte ändern.",
            why = "ẋ = Ax wird zu ẏᵢ = λᵢyᵢ; Hauptachsen des Trägheitstensors, Normalmoden, Energieeigenzustände sind alle dieselbe Idee."),
        c(M, 2, "ma_ode", "Was garantiert, dass ein Anfangswertproblem eine eindeutige Lösung hat (Picard-Lindelöf)?",
            "Die rechte Seite ist stetig und lokal Lipschitz-stetig im Zustand.", "Die Lösung ist ein Polynom.",
            "Die DGL ist linear und von zweiter Ordnung.", "Es gibt keine Anfangsbedingungen.",
            why = "Gegenbeispiel ohne Lipschitz: y' = √|y|, y(0) = 0 hat y ≡ 0 und y = t²/4. Determinismus in der Mechanik beruht auf dieser Bedingung."),
        c(M, 3, "ma_complex", "Warum ist eine im Komplexen differenzierbare Funktion so viel „starrer“ als eine reell differenzierbare?",
            "Komplexe Differenzierbarkeit verlangt die Cauchy-Riemann-Gleichungen; daraus folgen Analytizität und der Identitätssatz.",
            "Weil komplexe Zahlen zweidimensional sind und dadurch weniger Funktionen existieren.", "Weil nur Polynome holomorph sind.", "Das stimmt nicht.",
            why = "Holomorphe Funktionen sind beliebig oft differenzierbar, durch Werte auf einer Kurve festgelegt und erfüllen den Cauchyschen Integralsatz — Grundlage des Residuenkalküls."),
        c(M, 2, "ma_fourier", "Warum sind Fourier-Reihen bei linearen PDGL wie der Wärmeleitung so nützlich?",
            "Sinus- und Kosinusfunktionen sind Eigenfunktionen der Ableitung; jede Mode entwickelt sich unabhängig.", "Weil jede Funktion periodisch ist.",
            "Weil man so Integrale vermeidet.", "Weil sie immer gleichmäßig konvergieren.",
            why = "∂ₓ² sin(kx) = −k² sin(kx): Die PDGL wird zu entkoppelten ODEs, hochfrequente Moden klingen wie e^{−Dk²t} schnell ab."),
        c(M, 3, "ma_functional", "Was unterscheidet unendlichdimensionale Hilberträume wesentlich von ℝⁿ?",
            "Beschränkte Folgen haben nicht immer konvergente Teilfolgen; die Einheitskugel ist nicht kompakt.", "Sie haben kein Skalarprodukt.",
            "Sie sind nicht vollständig.", "In ihnen gibt es keine Basis.",
            why = "Eine Orthonormalfolge eₙ hat Abstände √2, also keine konvergente Teilfolge. Deshalb braucht man schwache Konvergenz und Kompaktheitsargumente."),
        c(M, 2, "ma_prob", "Warum sind so viele Messgrößen näherungsweise normalverteilt?",
            "Zentraler Grenzwertsatz: Summen vieler unabhängiger kleiner Einflüsse nähern sich einer Normalverteilung.",
            "Weil die Natur Gauß-Kurven bevorzugt.", "Weil Messgeräte so kalibriert werden.", "Das gilt nur für ganzzahlige Größen.",
            why = "Voraussetzung: unabhängige Beiträge mit endlicher Varianz. Bei schweren Verteilungsrändern (Cauchy) versagt der Satz."),
        c(M, 2, "ma_numerics", "Warum wird ein numerisches Ableiten mit sehr kleiner Schrittweite h wieder ungenauer?",
            "Rundungsfehler wachsen wie ε/h, während der Abschneidefehler mit h fällt; es gibt ein optimales h.", "Weil Computer keine kleinen Zahlen speichern können.",
            "Weil die Ableitung dann null wird.", "Das passiert nicht.",
            why = "Für die zentrale Differenz ist der Gesamtfehler ≈ ε/h + h²f'''/6, minimal bei h ~ ε^{1/3} ≈ 10⁻⁵ in doppelter Genauigkeit."),
        c(M, 3, "ma_tensor", "Warum schreibt man physikalische Gesetze gern in Tensorform?",
            "Eine Tensorgleichung, die in einem Koordinatensystem gilt, gilt in allen — die Physik hängt nicht von der Koordinatenwahl ab.",
            "Weil Tensoren einfacher als Vektoren sind.", "Weil Tensoren immer symmetrisch sind.", "Damit man keine Indizes braucht.",
